# Hypothesis: widening the year key of a functional TypedDict to int | str accepts both value types, while a dict literal missing a required key is still rejected.
from typing import TypedDict, reveal_type

Movie = TypedDict('Movie', {'name': str, 'year': int | str})


def get_year(movie: Movie) -> int | str:
    return movie['year']


def missing_name() -> Movie:
    return {'year': 1982}  # expect-error


movie1: Movie = {'name': 'Blade Runner', 'year': 1982}
movie2: Movie = {'name': 'Blade Runner', 'year': '1982'}
reveal_type(movie1['year'])
print(get_year(movie1), get_year(movie2))
print(missing_name())
